// Prépare la liste des pages à interroger sur l'API Recherche d'entreprises (data.gouv)
const cfg = $('Config').first().json;
const sd = $getWorkflowStaticData('global');
const manuel = $execution.mode !== 'production';
const modeTest = cfg.MODE_TEST === true || String(cfg.MODE_TEST).toLowerCase() === 'true' || manuel;
const nb = Math.max(1, Math.min(20, Number(cfg.PAGES_PAR_RUN) || 6));
if (!sd.liste_500plus) { sd.page = 1; sd.liste_500plus = true; } // nouvelle liste (500 salariés et +) : on la lit depuis le début
const debut = modeTest ? 1 : (Number(sd.page) || 1);
const out = [];
for (let p = debut; p < debut + nb && p <= 400; p++) {
  out.push({ json: { page: p, page_debut: debut, nb_pages: nb, mode_test: modeTest, execution_manuelle: manuel } });
}
return out;

