function depuisScalelist(b) {
  // Nœud Scalelist « Find Email » : renvoie la réponse brute de l'API, ou { error } en cas d'échec
  if (b && typeof b.error === 'string' && b.error) {
    const msg = b.error;
    if (/402|credit|quota|payment/i.test(msg)) return { error: '402 credits epuises (' + msg + ')' };
    if (/401|403|unauthor|forbidden|api key|invalid key/i.test(msg)) return { error: '401 api key (' + msg + ')' };
    if (/429|rate|limit|too many|timeout|ECONN|5\d\d/i.test(msg)) return { error: 'temporaire : ' + msg };
    return {}; // 404 / non trouvé
  }
  return b || {};
}
