  return `<!DOCTYPE html><html lang="fr"><head><meta charset="utf-8"><title>Lettre de motivation Adam Soufane</title><style>${CSS_BASE}
.page { width: 210mm; padding: 15mm 20mm 10mm 20mm; font-size: 10pt; line-height: 1.42; }
.exp b { font-size: 12.5pt; color: #1f3a5f; }
.exp { font-size: 10pt; line-height: 1.4; }
.dest { margin: 4mm 0 0 92mm; font-size: 10pt; line-height: 1.38; }
.date { margin: 6mm 0 0 92mm; }
.objet { margin: 7mm 0 5mm 0; font-weight: bold; color: #1f3a5f; }
p { margin: 0 0 3mm 0; text-align: justify; }
.sign { margin-top: 6mm; font-weight: bold; }
</style></head><body><div class="page">
