function mail(e) {
  const [lib] = secteur(e.section);
  const objet = `Candidature alternance Data Analyst (12 mois) - ${e.entreprise}`;
  const paras = [
    `Madame, Monsieur,`,
    `Étudiant en 3e année de BUT Science des Données à l'IUT Paris-Rives-de-Seine, je recherche une alternance de 12 mois en analyse de données, jusqu'en septembre 2027.`,
    `Cet été, j'ai effectué un stage de deux mois chez Veolia. J'y ai fiabilisé et mis à jour une base de données de près de 50 000 lignes, puis créé un tableau de bord qui permet aux équipes de la consulter facilement.`,
    `Je serais heureux de rejoindre ${e.entreprise}${lib ? `, dans le secteur ${lib},` : ''} et d'y mettre mes compétences en analyse de données au service de vos équipes. Pourriez-vous transmettre ma candidature à l'équipe concernée ? Vous trouverez mon CV et ma lettre de motivation en pièces jointes.`,
    `Je vous remercie par avance pour votre attention et reste disponible pour un échange.`,
    `Bien cordialement,`,
  ];
  const sigTexte = `${MOI.prenom} ${MOI.nom}\n${MOI.tel}\n${MOI.email}\nPortfolio : ${MOI.portfolio}\nLinkedIn : ${MOI.linkedin}`;
  const texte = paras.join('\n\n') + '\n' + sigTexte;
  const html = `<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#222">` +
    paras.map(p => `<p style="margin:0 0 12px 0">${esc(p)}</p>`).join('') +
    `<p style="margin:0"><b>${MOI.prenom} ${MOI.nom}</b><br>${MOI.tel}<br><a href="mailto:${MOI.email}">${MOI.email}</a><br>` +
    `<a href="${MOI.portfolio}">Portfolio</a> · <a href="${MOI.linkedin}">LinkedIn</a></p></div>`;
  return { objet, texte, html };
}


return $input.all().map(item => {
  const e = item.json;
  const m = mail(e);
  let objet = m.objet, html = m.html, texte = m.texte;
  if (e.mode_test) {
    const info = `TEST — en réel, ce mail partirait à ${e.dirigeant_prenom} ${e.dirigeant_nom} (${e.dirigeant_qualite}, ${e.entreprise}). ` +
      `Résultat Scalelist : ${e.email_pdg ? e.email_pdg + ' — statut ' + e.email_statut : 'aucun e-mail trouvé (statut ' + e.email_statut + ')'}.`;
    objet = '[TEST] ' + objet;
    html = `<div style="font-family:Arial,sans-serif;font-size:13px;background:#fff3cd;border:1px solid #e0b100;padding:10px;margin-bottom:16px">${esc(info)}<br><span style="color:#666">Réponse brute : ${esc(e.scalelist_reponse)}</span></div>` + html;
    texte = info + '\n\n' + texte;
  }
  const cv = cvHtml(e);
  const lettre = lettreHtml(e, new Date());
  // Gotenberg attend le HTML sous forme de fichier nommé index.html
  const fichierHtml = html => ({ data: Buffer.from(html, 'utf8').toString('base64'), mimeType: 'text/html', fileName: 'index.html', fileExtension: 'html' });
  return { binary: { cv_html: fichierHtml(cv), lettre_html: fichierHtml(lettre) }, json: {
    ...e,
    cv_html: cv,
    lettre_html: lettre,
    cv_fichier: 'CV_Adam_Soufane.pdf',
    lettre_fichier: `Lettre_motivation_Adam_Soufane_${slug(e.entreprise)}.pdf`,
    mail_objet: objet, mail_html: html, mail_texte: texte,
  } };
});

// Réunit les deux PDF (CV + lettre) sur chaque mail. Une candidature sans ses deux PDF n'est PAS envoyée :
// elle reste en file d'attente et repartira à la prochaine exécution (quota PDF épuisé, panne...).
const fiches = $('Rédaction CV + lettre + mail').all();
const cvs = $('Convert PDF – CV').all();
const lettres = $input.all();
const estPdf = b => !!(b && b.mimeType && /pdf/i.test(b.mimeType));
const out = [];
const manquants = [];
for (let i = 0; i < fiches.length; i++) {
  const j = fiches[i].json || {};
  const cv = cvs[i] && cvs[i].binary && cvs[i].binary.cv;
  const lm = lettres[i] && lettres[i].binary && lettres[i].binary.lettre;
  let ok = estPdf(cv) && estPdf(lm);
  if (ok) {
    try {
      const buf = await this.helpers.getBinaryDataBuffer(i, 'lettre');
      if (buf && buf.length && buf.slice(0, 4).toString('latin1') !== '%PDF') ok = false;
    } catch (err) { /* lecture impossible : on se fie au type du fichier */ }
  }
  if (!ok) { manquants.push(j.entreprise || 'élément ' + i); continue; }
  const { cv_html, lettre_html, ...reste } = j;
  out.push({
    json: { ...reste, pdf_manquants: 0 },
    binary: {
      cv: { ...cv, fileName: j.cv_fichier, mimeType: 'application/pdf', fileExtension: 'pdf' },
      lettre: { ...lm, fileName: j.lettre_fichier, mimeType: 'application/pdf', fileExtension: 'pdf' },
    },
  });
}
if (out.length === 0) {
  throw new Error(`PDF manquant pour toutes les candidatures (${manquants.join(', ')}). Aucun mail n'a été envoyé ; elles restent en file d'attente. Vérifie que Gotenberg tourne sur le serveur et que l'identifiant Basic Auth est correct.`);
}
for (const o of out) { o.json.pdf_manquants = manquants.length; o.json.pdf_manquants_noms = manquants.join(', '); }
return out;

// Mémorise les entreprises contactées (anti-doublon) et prépare le récapitulatif
const cfg = $('Config').first().json;
const sd = $getWorkflowStaticData('global');
sd.vus = sd.vus || {};
const prets = $('Assembler les pièces jointes').all().map(i => i.json);
const resultats = $input.all().map(i => i.json || {});
const parti = i => !!(resultats[i] && !resultats[i].error && (resultats[i].id || resultats[i].messageId || resultats[i].threadId));
const envois = prets.filter((e, i) => parti(i));
const echecs = prets.filter((e, i) => !parti(i));
const jour = new Date().toISOString().slice(0, 10);
const modeTest = prets.length ? prets[0].mode_test : true;
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
if (!modeTest) {
  const attente = { ...(sd.attente || {}) };
  const vus = { ...(sd.vus || {}) };
  for (const e of envois) { vus[e.siren] = { statut: 'envoye', date: jour, entreprise: e.entreprise, email: e.email_pdg, dirigeant: e.dirigeant_prenom + ' ' + e.dirigeant_nom }; delete attente[e.siren]; }
  sd.vus = vus; sd.attente = attente; sd.maj = Date.now();
}
const total = Object.values(sd.vus).filter(v => v.statut === 'envoye').length;
const lignes = envois.map(e => `<tr><td style="padding:4px 8px;border:1px solid #ccc">${esc(e.entreprise)}</td><td style="padding:4px 8px;border:1px solid #ccc">${esc(e.dirigeant_prenom + ' ' + e.dirigeant_nom)}</td><td style="padding:4px 8px;border:1px solid #ccc">${esc(e.email_pdg || '—')}</td><td style="padding:4px 8px;border:1px solid #ccc">${esc(e.email_statut)}</td></tr>`).join('');
const titre = modeTest ? `[TEST] ${envois.length} candidature(s) générée(s) et envoyée(s) à ton adresse` : `${envois.length} candidature(s) envoyée(s) aujourd'hui`;
const html = `<div style="font-family:Arial,sans-serif;font-size:14px"><p><b>${esc(titre)}</b></p>` +
  `<table style="border-collapse:collapse;font-size:13px"><tr><th style="padding:4px 8px;border:1px solid #ccc">Entreprise</th><th style="padding:4px 8px;border:1px solid #ccc">Dirigeant</th><th style="padding:4px 8px;border:1px solid #ccc">E-mail (Scalelist)</th><th style="padding:4px 8px;border:1px solid #ccc">Statut</th></tr>${lignes}</table>` +
  (prets.length ? `<p>Recherches Scalelist effectuées : ${esc(prets[0].nb_recherches)} · crédits consommés : ${esc(prets[0].credits_utilises)} · objectif du jour : ${esc(prets[0].objectif)} · envoyés : ${esc(envois.length)}${prets[0].credits_scalelist !== null && prets[0].credits_scalelist !== undefined ? ' · crédits Scalelist avant recherche : ' + esc(prets[0].credits_scalelist) : ''}.</p>` : '') +
  (prets.length && prets[0].pdf_manquants ? `<p style="color:#b00020"><b>${esc(prets[0].pdf_manquants)} candidature(s) sans PDF (Gotenberg indisponible ?), reprises à la prochaine exécution :</b> ${esc(prets[0].pdf_manquants_noms)}</p>` : '') +
  (echecs.length ? `<p style="color:#b00020"><b>${echecs.length} envoi(s) en échec, repris à la prochaine exécution :</b> ${esc(echecs.map(e => e.entreprise).join(', '))}</p>` : '') +
  (prets.length && prets[0].alerte_quota ? `<p style="color:#b00020"><b>Limite Scalelist atteinte (50 recherches/jour sur le plan gratuit) : la recherche s'est arrêtée avant l'objectif.</b></p>` : '') +
  (prets.length && prets[0].alerte_credits ? `<p style="color:#b00020"><b>Crédits Scalelist épuisés : la recherche s'est arrêtée avant l'objectif.</b></p>` : '') +
  (modeTest ? `<p>Mode test : aucun mail n'est parti vers un dirigeant.</p>` : `<p>Total envoyé depuis le début : ${total}.</p>`) + `</div>`;
return [{ json: { destinataire: cfg.EMAIL_TEST, objet: (modeTest ? '[TEST] ' : '') + `Récap candidatures alternance – ${jour} – ${envois.length} envoi(s)`, html, nb: envois.length, mode_test: modeTest } }];
